--- src/RefundService.php:base
+++ src/RefundService.php:current
@@ -4,7 +4,7 @@

 final class RefundService
 {
-    public const VERSION = 'v1';
+    public const VERSION = 'v2';

     /**
      * @return array<string, mixed>
@@ -25,15 +25,75 @@
         if ($requestedPercent < 1 || $requestedPercent > 100) {
             throw new \InvalidArgumentException('requested percent must be between 1 and 100');
         }
-        if ($requestedPercent !== 100) {
+
+        if ($requestedPercent === 100) {
+            return [
+                'amount_cents' => $amountCents,
+                'refund_percent' => 100,
+                'refund_cents' => $amountCents,
+                'mode' => 'full',
+            ];
+        }
+
+        $policy = self::policy();
+
+        if (($policy['partial_refund_enabled'] ?? false) !== true) {
             throw new \InvalidArgumentException('partial refunds are not enabled');
         }

+        $partialPolicy = $policy['partial_refund'] ?? null;
+        if (!is_array($partialPolicy)) {
+            throw new \InvalidArgumentException('partial refund policy is missing');
+        }
+
+        $minAmountCents = (int) ($partialPolicy['min_amount_cents'] ?? 0);
+        $partialMaxPercent = (int) ($partialPolicy['max_percent'] ?? 0);
+
+        if ($amountCents < $minAmountCents) {
+            throw new \InvalidArgumentException('amount is below the partial refund minimum');
+        }
+        if ($requestedPercent > $partialMaxPercent) {
+            throw new \InvalidArgumentException('requested percent exceeds the partial refund maximum');
+        }
+
+        $tierMaxPercent = self::tierMaxPercent($policy['tiers'] ?? [], $amountCents);
+        if ($tierMaxPercent === null) {
+            throw new \InvalidArgumentException('no refund tier covers this amount');
+        }
+        if ($requestedPercent > $tierMaxPercent) {
+            throw new \InvalidArgumentException('requested percent exceeds the tier maximum');
+        }
+
         return [
             'amount_cents' => $amountCents,
-            'refund_percent' => 100,
-            'refund_cents' => $amountCents,
-            'mode' => 'full',
+            'refund_percent' => $requestedPercent,
+            'refund_cents' => (int) round($amountCents * $requestedPercent / 100),
+            'mode' => 'partial',
         ];
     }
+
+    /**
+     * @param array<int, array<string, mixed>> $tiers
+     */
+    private static function tierMaxPercent(array $tiers, int $amountCents): ?int
+    {
+        $selected = null;
+        $selectedMin = null;
+
+        foreach ($tiers as $tier) {
+            if (!is_array($tier)) {
+                continue;
+            }
+            $tierMin = (int) ($tier['min_amount_cents'] ?? 0);
+            if ($tierMin > $amountCents) {
+                continue;
+            }
+            if ($selectedMin === null || $tierMin >= $selectedMin) {
+                $selectedMin = $tierMin;
+                $selected = (int) ($tier['max_refund_percent'] ?? 0);
+            }
+        }
+
+        return $selected;
+    }
 }
